/// <summary>
/// MPJ_17845_PBMSProductMDRItemSite
/// Extension of Purchtable form datasource of PurchLine
/// </summary>
[ExtensionOf(formDataSourceStr(PurchTable,PurchLine))]
final class METPurchTableFormPurchLineDs_Extension
{   
}

Method.Source:
    void itemIdModified()
    {
        InventItemPurchSetup    inventItemPurchSetup;
        PurchLine               purchLine = this.formRun().dataSource().cursor();
        FormDataSource          datasourceInventDim      = this.formRun().dataSource(formDataSourceStr(PurchTable,InventDim)) as FormDataSource ;
        InventDim               inventDimLoc    = datasourceInventDim.cursor();
        InventDim               inventDimPurch;

        next itemIdModified();

        //MPJ_17845_PBMSProductMDRItemSite on 04 March 2022 by Sathish - Start
        //inventItemPurchSetup = InventItemPurchSetup::find(purchLine.ItemId ,purchLine.InventDimId);
        select firstonly inventItemPurchSetup
        where inventItemPurchSetup.ItemId == purchLine.ItemId
            join inventDimPurch
                where inventDimPurch.inventDimId == inventItemPurchSetup.InventDimId
                    &&  inventDimPurch.InventSiteId == inventDimLoc.InventSiteId;

        purchLine.PurchUnit  = inventItemPurchSetup.METPurchUnit;
        //MPJ_17845_PBMSProductMDRItemSite - End
    }
